def outputs():
    return {LABS/lab['route']:page(lab, CONTENT[lab['id']], 'tabular.js', 'm3')
            for lab in load_registry()['labs'] if lab['id'] in CONTENT}

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--write',action='store_true');args=parser.parse_args()
    for path,content in outputs().items():
        if args.write:
            path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding='utf-8')
        elif not path.exists() or path.read_text(encoding='utf-8')!=content:
            raise SystemExit('Stale M3 page. Run build_tabular_pages.py --write.')
    print('Four M3 pages '+('generated.' if args.write else 'are current.'))

if __name__=='__main__':main()
